import json,random,collections,statistics
x=json.load(open('/tmp/data.json'))['questions']
def evalpol(name,fn):
 ok=0
 for q in x: ok+=fn(q)==q['correct_answer']
 print(name,ok/len(x),ok)
def choose(ss,mode='sum'):
 d={}; cnt=collections.Counter(); best={}
 for s in ss:
  a=s['answer'];cnt[a]+=1;d[a]=d.get(a,0)+s['score'];best[a]=max(best.get(a,-99),s['score'])
 if mode=='sum':return max(d,key=d.get)
 if mode=='cnt':return cnt.most_common(1)[0][0]
 if mode=='hyb':return max(cnt,key=lambda a:(cnt[a],d[a]))
 if mode=='sumcnt':return max(d,key=lambda a:d[a]+.35*cnt[a])
 if mode=='avg':return max(d,key=lambda a:d[a]/cnt[a])
for mode in ['sum','cnt','hyb','sumcnt','avg']:
 evalpol('oneeach '+mode,lambda q,m=mode:choose([next(s for s in q['samples'] if s['variant']==v) for v in range(5)]+[q['samples'][0]],m))
# deterministic take first k per variant allocations
for alloc in [(6,0,0,0,0),(2,1,1,1,1),(1,1,1,1,2),(0,0,2,2,2),(3,1,1,0,1),(1,2,1,1,1)]:
 ss=[]
 for q in x:
  z=[]
  for v,k in enumerate(alloc):z += [s for s in q['samples'] if s['variant']==v][:k]
  ss.append(z)
 for mode in ['sum','cnt','sumcnt']:
  print(alloc,mode,sum(choose(z,mode)==q['correct_answer'] for z,q in zip(ss,x))/len(x))
