def run(env):
    qs = env.questions
    data = {}
    for q in qs:
        z=[]
        for _ in range(2):
            a,s=env.sample(q['id'],0)
            z.append((a,s))
        # Low verifier confidence is the useful signal for where to spend the pool.
        # Include disagreement as a mild difficulty penalty.
        vals=[s for a,s in z]
        conf=sum(vals)/2.0
        if z[0][0] != z[1][0]: conf -= 0.25
        data[q['id']]={'z':z,'conf':conf}
    # Concentrate the remaining calls on the least confident questions.
    extra=env.budget-2*len(qs)
    order=sorted(qs,key=lambda q:data[q['id']]['conf'])
    for q in order:
        if extra < 10: break
        d=data[q['id']]
        for _ in range(10):
            a,s=env.sample(q['id'],0); d['z'].append((a,s))
        extra-=10
    # Distribute any remainder safely, one call at a time.
    i=0
    while extra:
        q=order[i % len(order)]; a,s=env.sample(q['id'],0)
        data[q['id']]['z'].append((a,s)); extra-=1; i+=1
    out={}
    for q in qs:
        d={}
        for a,s in data[q['id']]['z']:
            d[a]=d.get(a,0.0)+s
        out[q['id']]=max(d,key=d.get)
    env.submit(out)
